/* Original beginner explanations and annotated teaching diagrams. */
const beginnerTerms={
 '操作系统':'管理电脑硬件、文件和程序的软件。Windows、Linux、macOS 都是操作系统；不是某个网页。',
 '服务器':'为其他设备提供服务的电脑或程序。例如网站服务器接收浏览器请求并返回页面。服务器不一定长得像机柜，也可以在普通电脑上运行。',
 '终端':'有两个常见意思：网络里的终端是手机、电脑等使用网络的设备；命令行终端是输入文字指令、查看结果的窗口。看上下文区分。',
 'Shell':'读取并解释命令的程序。终端提供窗口，Shell 处理你输入的命令；Linux 常用 Bash，Windows 常用 PowerShell，它们的语法不完全相同。',
 '命令':'让程序执行动作的一行文字。例如 pwd 查看当前位置。空格用来分隔命令名和参数；教学中的 $ 提示符不要复制。',
 '目录':'放文件和其他目录的容器，也叫文件夹。Linux 的 / 是整棵目录树的起点，/home/student 是其中一条完整路径。',
 '路径':'文件或目录的位置描述。绝对路径从 / 开始；相对路径从当前位置开始。Windows 的 C:\\ 和 Linux 的 / 是不同写法。',
 '网卡':'设备连接网络的接口部件，有线网卡连接网线，无线网卡连接 Wi-Fi。一台电脑可以有多个网络接口。',
 'MAC 地址':'用于当前链路通信的接口地址，通常写成六组十六进制数字，如 02:1A:2B:3C:4D:5E。可以类比本地收件标签；它不是 IP，也不是可靠的身份证，可被修改或随机化。',
 'IP 地址':'网络通信使用的逻辑地址。例如 IPv4 的 192.168.10.20。可以类比网络中的投递地址；地址可能变化，一台设备可以有多个 IP。',
 '交换机':'连接同一局域网中的多个有线设备。常见二层交换机学习 MAC 地址在哪个端口，再转发数据；初学先理解这个职责，部分高级交换机也能做路由。',
 '局域网':'范围较小、由同一方管理的网络，例如办公室网络。是不是同一 IP 网段还需要地址和掩码判断，不能只看两台设备离得近。',
 '路由器':'在不同网络之间转发数据的设备，按目标 IP 和路由表选择下一跳。家用路由器常同时包含交换机、无线接入和地址分配功能。',
 '网关':'本机配置的通往其他网络的下一跳地址。默认网关通常是路由器在本地网段的接口 IP；网关是一个角色，不是另一种必须单独购买的盒子。',
 'DNS':'域名系统。把域名（如 example.com）查询成 IP 等记录；浏览器再用结果连接服务器。解析成功不等于网页一定正常，缓存和多地址也会影响结果。',
 'AP':'无线接入点，让 Wi-Fi 设备接入局域网。它的基本职责是无线接入；并非每个 AP 都负责跨网段路由。',
 '端口':'两个意思：交换机端口是插网线的物理接口；TCP/UDP 端口是程序通信的编号，如 HTTPS 常用 TCP 443。不要把端口号当成网线插孔。',
 'DHCP':'自动分配 IP、掩码、网关、DNS 等网络配置的机制。它与 DNS 分工不同：一个发配置，一个查名字。',
 '掩码':'帮助 IP 地址区分网络部分与主机部分的配置。/24 是前缀长度，在 IPv4 中对应 255.255.255.0；不同前缀的地址范围不同。',
 '服务':'持续等待并处理请求的程序，例如网站服务和数据库服务。程序启动不代表它的每个业务功能都正常。',
 '日志':'程序按时间记录的事件文本，例如请求、状态和错误。找日志要先知道哪个程序处理了请求、日志在哪里，再按时间或请求标识定位。',
 '管道':'用 | 把前一个命令的输出送给后一个命令处理。例如先读日志，再筛选错误；它不是网络线缆。',
 'HTTP':'浏览器与网站交换请求和响应的一种协议。HTTPS 在传输中加入加密与服务器身份验证；状态码如 200、404、500 描述这次响应。',
 'SQL':'查询和管理数据库的一种语言。SELECT 通常用于读取；写入、删除等操作需要额外谨慎。',
 '数据库':'按规则保存和查询数据的软件系统。表像有列名的数据表格；业务页面里的字段可能来自一个或多个表。',
 '容器':'把应用及其运行所需内容组织成隔离运行环境的方式。Docker 是常见工具，容器仍依赖宿主机资源。'
};
const beginnerRows=[
 ['computer','先认电脑和服务器','操作系统','你正在用浏览器打开网站。浏览器是程序，Windows 或 Linux 是操作系统，电脑是硬件。网站背后通常有服务器接收请求；不是把网页存在你屏幕里就算服务器。','像餐厅：你是顾客，浏览器替你点菜，服务器接单并准备结果。这个比喻只帮助理解分工，不代表真实网络是一条直线。','你打开网站时，浏览器主要扮演什么角色？','发出请求、展示返回的页面',['代替网站保存全部数据库','就是网线本身'],'浏览器是使用服务的客户端，网站由服务器提供。','computer'],
 ['terminal','终端窗口：哪部分要输入？','终端','这里的终端指命令行窗口。提示符表示它在等你输入；命令写在提示符后，按回车执行；下一行输出是程序给你的结果，不要再当命令输入。本网站的黑色练习区是教学模拟，不是你的电脑或公司服务器。','示意：student@lab:~$ pwd\n/home/student\n第一行只输入 pwd。第二行是结果。$ 不要复制；~ 表示用户家目录。','示意窗口显示 $ pwd 时，你应输入什么？','pwd',['$ pwd','/home/student'],'提示符和结果都不属于本次输入。Windows PowerShell 也有提示符，但真实系统命令可能不同。','terminal'],
 ['path','文件、目录与路径：先知道在哪里','目录','目录就是文件夹。Linux 用 / 从根目录开始分层，/home/student/notes.txt 指向 student 目录中的 notes.txt 文件。pwd 查看当前位置，ls 查看当前位置里的名字，cd 改变当前位置；这三件事不要混在一起。','当前位置 /home/student\n绝对路径 /home/student/notes.txt\n相对路径 notes.txt\n上一级 .. → /home','已经在 /home/student，notes.txt 是什么路径？','相对当前目录的路径',['从根目录开始的绝对路径','一定是网络地址'],'没有以 / 开头，所以需要结合当前位置理解。','directory'],
 ['device','网络终端、网卡和连接','网卡','在网络课中，终端指使用网络的设备，如电脑和手机，不是黑色命令窗口。网卡负责把设备接入网络。有线网卡接网线，无线网卡通过 Wi-Fi 接入 AP；Wi-Fi 信号好也不代表互联网一定可用。','电脑的有线网卡 → 网线 → 交换机\n手机的无线网卡 → Wi-Fi → AP\n这里先认识连接，不配置任何真实设备。','网络课里的“终端”可以是什么？','正在使用网络的电脑或手机',['只能是黑色命令窗口','只能是 DNS 服务器'],'同一个术语在不同上下文可能有不同意思。','network-device'],
 ['mac','MAC 地址：当前链路的收件标签','MAC 地址','MAC 常见写法是 02:1A:2B:3C:4D:5E：六组，每组两个字符，字符来自 0–9 和 A–F。它标识网络接口在链路上的地址。先能认出它即可，不需要现在记位数或背协议。一个设备的有线和无线接口通常各有地址；MAC 可修改或随机化，不能作为可靠身份认证。','MAC 示例：02:1A:2B:3C:4D:5E\nIPv4 示例：192.168.10.20\n二者负责不同层次，不要互换填写。','下面哪个是本课中的 MAC 地址写法？','02:1A:2B:3C:4D:5E',['192.168.10.20','example.com'],'冒号分隔的六组十六进制数是常见 MAC 写法；另外两个是 IPv4 地址和域名。','addresses'],
 ['switch','交换机：把本地设备连接起来','交换机','交换机常有一排插网线的口。每个物理端口连接一个设备或其他网络设备。常见二层交换机学习“哪个 MAC 从哪个端口来”，再决定数据往哪个口送；不知道目标时也可能向相关端口转发询问。不是所有数据都会永远只发一个端口。','端口 1 ← 电脑 A（MAC A）\n端口 2 ← 电脑 B（MAC B）\n已知道 B 在端口 2 → 发给 B 的数据走端口 2','常见二层交换机主要根据什么转发？','MAC 地址和它对应的端口',['网页里的用户名','文件夹路径'],'先理解同一链路中的转发；支持路由的高级交换机在后面学习。','switch-board'],
 ['ip','IP 地址与网段：网络里的位置','IP 地址','IPv4 常写成四组十进制数字，例如 192.168.10.20。掩码或前缀告诉设备哪些地址属于本地网段。这里规定两台电脑都是 /24：192.168.10.20 与 192.168.10.30 属于同一网段，192.168.20.30 属于另一网段。只看地址的前几组而忽略掩码会出错。','本课 /24 示例：\n电脑 A：192.168.10.20/24\n电脑 B：192.168.10.30/24\n另一个网段：192.168.20.30/24','在本课的 /24 条件下，哪个地址与 192.168.10.20 同网段？','192.168.10.30',['192.168.20.30','不能查看掩码就随机决定'],'本题明确给出 /24，前三组相同；这不是所有掩码都适用的口诀。','addresses'],
 ['gateway','网关与路由器：去别的网络怎么走？','网关','路由器是负责在不同网络之间转发的设备；网关是你这台设备通向其他网络时使用的下一跳。假设电脑是 192.168.10.20/24，路由器在本地接口是 192.168.10.1，这个 .1 可以配置为默认网关。它不是网站最终地址，也不是每台电脑都固定必须填 .1。','电脑 .20 → 本地网关 .1 → 上联网络 → 网站服务器\n家用“路由器”盒子常还包含交换机和 AP，功能上仍可分开理解。','默认网关一般用于什么？','把需要去其他网络的数据交给下一跳',['把所有域名直接变成文件夹','作为每台设备唯一的 MAC 地址'],'网关负责下一跳，路由器继续按路由选择方向；DNS 负责名字查询。','gateway-map'],
 ['dns','DNS：先查名字，再连接网站','DNS','人容易记住 example.com，网络连接需要相应的地址。DNS 可以查询域名对应的 IP 等记录。它像查通讯录：查到号码后还要拨号并由对方回应，查到 IP 后也还要建立连接并收到网站响应。DNS 失败、网络不通和网站服务报错是不同问题。','1 输入域名 example.com\n2 查询 DNS → 得到示例 IP 192.0.2.10\n3 连接这个地址上的服务\n4 收到网页响应\n192.0.2.10 是文档示例地址，不供本课实际访问。','DNS 查到 IP，能保证网页正常吗？','不能，还需要连接和网站服务正常',['能，查到就等于已打开网页','能，DNS 会修好数据库'],'名字查询只是其中一步，不能代替后续验证。','dns-map'],
 ['request','串起来：打开网页发生了什么？','服务','先有网络连接和地址配置，再查询域名，然后沿本地网络和网关连接网站服务，最后收到响应。查名字本身也需要网络，实际系统还可能使用缓存，因此图是分工示意，不是每次都严格执行的抓包顺序。排查时把“无线已连”“解析有结果”“网页收到响应”分别核实。','教学场景：Wi-Fi 已连接，DNS 返回 IP，但网站响应 500。\n已有响应说明这次请求到达了响应者；还需查处理请求的服务和日志，不能直接认定是 DNS 或数据库坏了。','已经收到网站的 500 响应，下一步较合理的是？','按请求时间和标识查看相关服务日志',['因为能连 Wi-Fi 就宣布业务正常','立即删除数据库'],'响应与业务成功不同。日志能提供下一步证据，500 本身不能确定根因。','request-map']
];
function beginnerLesson(row,prefix){const [id,title,term,body,example,q,right,wrong,reason,diagram]=row;return {id:prefix+id,section:'零基础 · 先认识',title,summary:body.split('。')[0]+'。',body:[body],examples:[{text:example,meaning:reason}],related:beginnerTerms[term],source:['初学词典：随时展开查词','#beginner-glossary'],diagram,beginner:true,terms:[term],tasks:[choiceTask(q,right,wrong,reason),choiceTask('看懂后再判断：'+reason,right,['跳过题目，直接进入下一关','不看上下文，只背一个词'],reason)],quiz:choiceTask(q,right,wrong,reason,1)};}
