const oldBeginnerLesson=beginnerLesson;beginnerLesson=function(row,prefix){const c=oldBeginnerLesson(row,prefix);const i=beginnerRows.indexOf(row);const [q,right,wrong,reason]=beginnerChecks[i];c.tasks[1]=choiceTask(q,right,wrong,reason,1);return c;};
hubSubjects.beginner={name:'零基础准备',mark:'起',tag:'不懂术语也能开始',description:'从电脑、终端窗口和目录树，到 MAC、交换机、网关与 DNS，先看图再做题。',tone:'teal'};
hubCurriculum.beginner=beginnerRows.map(r=>beginnerLesson(r,'start-'));
hubCurriculum.network.unshift(...beginnerRows.slice(3).map(r=>beginnerLesson(r,'net-start-')));
